BLOBS = [
    ('app.log', 50, 5),
    ('backup.vhd', 500, 45),
    ('archive-2019.tar', 1000, 200),
]
RATES = {'hot': 0.020, 'cool': 0.010, 'archive': 0.002}

def tier_for(age_days):
    if age_days >= 90:
        return 'archive'
    if age_days >= 30:
        return 'cool'
    return 'hot'

def monthly_cost(size_gb, tier):
    return size_gb * RATES[tier]

total = 0.0
for name, size_gb, age_days in BLOBS:
    tier = tier_for(age_days)
    cost = monthly_cost(size_gb, tier)
    total += cost
    print(f'{name} | {tier} | ${cost:.2f}')
print(f'TOTAL | ${total:.2f}')
